//! Explicit, finite disclosure for one original learned release. The live actor
//! gets exact-policy observations, never generated bytes or either effect key.
use super::{Config, PeerProfile};
use super::super::{Profile, precheck};
use std::path::Path;

pub(super) use precheck::{Service, Settings, check_owner_epoch};

const USAGE: &str = "learned --precheck-profile requires --actor-profile in a single live learned publication command; historical, actorless and sequence modes cannot acquire a disclosure";

/// Validate the WHOLE live grammar before stripping this option. It cannot turn
/// a historical/maintenance command into a live source-acquiring invocation.
pub(super) fn take_option(args: &[String]) -> Result<(Vec<String>, Option<&Path>), String> {
    let mut positions = args.iter().enumerate().filter(|(_, arg)| *arg == "--precheck-profile");
    let Some((at, _)) = positions.next() else { return Ok((args.to_vec(), None)); };
    if positions.next().is_some() || at < 4 { return Err(USAGE.into()); }
    let path = args.get(at + 1).ok_or(USAGE)?;
    if path.is_empty() || path.starts_with("--") { return Err(USAGE.into()); }
    let mut remaining = args[..at].to_vec();
    remaining.extend_from_slice(&args[at + 2..]);
    let (_, actor) = super::ingress::take_option(&remaining)?;
    if actor.is_none() { return Err(USAGE.into()); }
    Ok((remaining, Some(Path::new(path))))
}

#[derive(Clone)]
pub(super) struct Selection {
    pub settings: Settings,
    pub reviewer: PeerProfile,
}

pub(super) fn check(settings: &Settings, config: &Config, actor: Option<&Profile>,
    reviewer: &PeerProfile) -> Result<(), String>
{
    precheck::check_learned(settings)?;
    settings.check_host(config, actor.ok_or(USAGE)?, reviewer)
}
